use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::{Datelike, Duration, NaiveDate};
use std::collections::BTreeMap;

pub struct BillWeeklyCommand;

/// The billing amount for a completed entry is its stored duration in seconds.
/// Keeping this calculation here gives all billing views one place to share it.
fn billing_seconds(entry: &TimeEntry) -> Option<i64> {
    if entry.billable && !entry.is_running() {
        Some(entry.duration)
    } else {
        None
    }
}

fn week_monday(entry: &TimeEntry) -> NaiveDate {
    let date = entry.start.date_naive();
    date - Duration::days(date.weekday().num_days_from_monday() as i64)
}

fn weekly_totals(entries: &[TimeEntry]) -> BTreeMap<NaiveDate, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries {
        if let Some(seconds) = billing_seconds(entry) {
            *totals.entry(week_monday(entry)).or_insert(0) += seconds;
        }
    }
    totals
}

fn render_totals(totals: &BTreeMap<NaiveDate, i64>) -> String {
    if totals.is_empty() {
        return "(no data)\n".to_string();
    }

    let total: i64 = totals.values().sum();
    let mut output = String::new();
    for (monday, seconds) in totals {
        output.push_str(&format!("{}  {seconds}s\n", monday.format("%Y-%m-%d")));
    }
    output.push_str(&format!("Total  {total}s\n"));
    output
}

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        print!("{}", render_totals(&weekly_totals(&entries)));
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{DateTime, Utc};

    fn entry(start: &str, duration: i64, billable: bool, running: bool) -> TimeEntry {
        let start = DateTime::parse_from_rfc3339(start)
            .unwrap()
            .with_timezone(&Utc);
        TimeEntry {
            id: 1,
            description: String::new(),
            start,
            stop: (!running).then_some(start),
            duration: if running {
                -start.timestamp()
            } else {
                duration
            },
            billable,
            workspace_id: 1,
            tags: vec![],
            project: None,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn groups_billable_completed_entries_by_utc_monday() {
        let entries = vec![
            entry("2026-01-04T23:30:00Z", 30, true, false),
            entry("2026-01-05T00:30:00Z", 60, true, false),
            entry("2026-01-06T00:30:00Z", 999, false, false),
            entry("2026-01-07T00:30:00Z", 999, true, true),
        ];

        let totals = weekly_totals(&entries);
        assert_eq!(totals[&NaiveDate::from_ymd_opt(2025, 12, 29).unwrap()], 30);
        assert_eq!(totals[&NaiveDate::from_ymd_opt(2026, 1, 5).unwrap()], 60);
    }

    #[test]
    fn renders_empty_and_total_output() {
        assert_eq!(render_totals(&BTreeMap::new()), "(no data)\n");

        let mut totals = BTreeMap::new();
        totals.insert(NaiveDate::from_ymd_opt(2026, 1, 5).unwrap(), 60);
        assert_eq!(render_totals(&totals), "2026-01-05  60s\nTotal  60s\n");
    }
}
